package operators;

public class Relational {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n1=10,n2=20;
		
		boolean a=n1>=n2;
		boolean b=n1<=n2;
		boolean c=n1==n2;
		boolean d=n1!=n2;
		System.out.println(a);
		System.out.println(b);
		System.out.println(c);
		System.out.println(d);


	}

}
